import { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import './DashboardCandidat.css';

// Idéalement dans un .env : REACT_APP_API_URL=http://localhost:5000
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Palette d'avatars dérivée du nom de l'entreprise (déterministe, pas de random)
const AVATAR_COLORS = ['#185fa5', '#2a9d8f', '#8e6bb0', '#c9822a', '#4a6fa5'];
function getAvatarColor(name = '') {
  const sum = [...name].reduce((acc, c) => acc + c.charCodeAt(0), 0);
  return AVATAR_COLORS[sum % AVATAR_COLORS.length];
}

export default function DashboardCandidat() {
  const [jobs, setJobs] = useState([]);
  const [status, setStatus] = useState('loading'); // 'loading' | 'success' | 'error'
  const [search, setSearch] = useState('');

  useEffect(() => {
    const controller = new AbortController();

    fetch(`${API_URL}/api/jobs`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Erreur serveur (${res.status})`);
        return res.json();
      })
      .then((data) => {
        setJobs(data);
        setStatus('success');
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Erreur chargement jobs:', err);
          setStatus('error');
        }
      });

    return () => controller.abort();
  }, []);

  // Calculé une seule fois par changement de liste, pas à chaque rendu
  const jobsWithFreshness = useMemo(() => {
    const DAY_MS = 24 * 60 * 60 * 1000;
    return jobs.map((job) => ({
      ...job,
      isNew: Date.now() - new Date(job.createdAt).getTime() < DAY_MS,
    }));
  }, [jobs]);

  const filteredJobs = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return jobsWithFreshness;
    return jobsWithFreshness.filter(
      (job) =>
        job.title.toLowerCase().includes(q) ||
        job.company.toLowerCase().includes(q)
    );
  }, [jobsWithFreshness, search]);

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h2 className="dashboard-title">Offres d'emploi disponibles</h2>
        <p className="dashboard-subtitle">
          {status === 'success' && `${filteredJobs.length} offre${filteredJobs.length > 1 ? 's' : ''} trouvée${filteredJobs.length > 1 ? 's' : ''}`}
        </p>

        <div className="search-wrapper">
          <svg className="search-icon" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
            <circle cx="11" cy="11" r="7" fill="none" stroke="currentColor" strokeWidth="2" />
            <line x1="16.5" y1="16.5" x2="21" y2="21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
          <input
            type="text"
            className="search-input"
            placeholder="Rechercher par poste ou entreprise..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            aria-label="Rechercher une offre"
          />
        </div>
      </header>

      {status === 'loading' && (
        <div className="offres-list" aria-busy="true" aria-label="Chargement des offres">
          {Array.from({ length: 3 }).map((_, i) => (
            <div className="job-card job-card-skeleton" key={i}>
              <div className="skeleton-line skeleton-title" />
              <div className="skeleton-line skeleton-text" />
              <div className="skeleton-line skeleton-link" />
            </div>
          ))}
        </div>
      )}

      {status === 'error' && (
        <div className="state-panel state-error">
          <p>Impossible de charger les offres pour le moment.</p>
          <p className="state-panel-hint">Vérifiez votre connexion et réessayez plus tard.</p>
        </div>
      )}

      {status === 'success' && filteredJobs.length === 0 && (
        <div className="state-panel state-empty">
          <p>Aucune offre ne correspond à votre recherche.</p>
        </div>
      )}

      {status === 'success' && filteredJobs.length > 0 && (
        <div className="offres-list">
          {filteredJobs.map((job) => (
            <div key={job.id} className="job-card">
              <div className="job-card-header">
                <div className="job-card-heading">
                  <div
                    className="job-card-avatar"
                    style={{ backgroundColor: getAvatarColor(job.company) }}
                    aria-hidden="true"
                  >
                    {job.company?.charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <h3 className="job-card-title">{job.title}</h3>
                    <p className="job-card-company">{job.company}</p>
                  </div>
                </div>
                {job.isNew && <span className="job-card-badge">Nouveau</span>}
              </div>

              <Link to={`/job/${job.id}`} className="job-card-link">
                Voir le détail
                <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
                  <path d="M5 12h14M13 6l6 6-6 6" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </Link>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
